module top_module(light, clock)  ;input clock ; 
    output reg [2:0]light ;  
    reg [2:0] state ; 
    parameter S0 = 0 , S1 =1 , S2 = 2; 
    parameter RED = 3'b100 , GREEN = 3'b010 , YELLOW = 3'b001 ;

    always@(posedge clock)
        begin
            case (state) 
                S0 : state <= S1 ; 
                S1 : state <= S2 ; 
                S2 : state <= S0 ;  
                default  : state <= S0 ; 
            endcase 
        end 
    always @(state)
        begin
            case (state) 
                S0 : light <= RED ; 
                S1 : light <= GREEN ; 
                S2 : light <= YELLOW ;  
                default  : light <= RED ; 
            endcase 
        end
endmodule

