description:
Design a sequential read-only memory (ROM) module that outputs a 4-bit value based on a 3-bit counter, cycling through predefined values on each clock cycle. The counter increments with each clock pulse, and upon reaching a count of 3, it resets to 0. The output `dout` provides a sequence of values (3, 2, 1, 0) corresponding to the counter state, effectively creating a simple counter-driven ROM that operates in a loop until reset. The module also includes a reset functionality to initialize the counter back to 0 when activated.
module top_module(
    clk,
    rst,
    dout
);

code:
module top_module(
    clk,
    rst,
    dout
);input clk;
input rst;
output [3:0] dout;
reg [3:0] dout;

reg [2:0] Count = 0;



always @(posedge clk) begin: SEQROMEX_COUNTER
    if (rst) begin
        Count <= 0;
    end
    else if ((Count == 3)) begin
        Count <= 0;
    end
    else begin
        Count <= (Count + 1);
    end
end


always @(posedge clk) begin: SEQROMEX_MEMORY
    case (Count)
        'h0: begin
            dout <= 3;
        end
        'h1: begin
            dout <= 2;
        end
        'h2: begin
            dout <= 1;
        end
        'h3: begin
            dout <= 0;
        end
    endcase
end

endmodule

